effect.shader:
const float PI = 3.14159265;

/** A coordenada da faixa, em faixas, num ponto (px do buffer, relativo ao Centro). */
float coordenada(vec2 d, float tam) {
    float th = radians(rotation);
    float c = cos(th);
    float s = sin(th);
    // Para o espaço da forma (a rotação do AE gira a forma no sentido horário).
    vec2 u = vec2(d.x * c + d.y * s, -d.x * s + d.y * c);
    float a = aspect / 100.0;
    vec2 e = vec2(u.x, u.y / a);
    if (geometry == 0) return -u.y / tam + 0.5;
    if (geometry == 1) return length(e) / tam;
    if (geometry == 2) return max(abs(e.x), abs(e.y)) / tam;
    if (geometry == 3) {
        float n = max(points, 3.0);
        float setor = 2.0 * PI / n;
        float ang = atan(u.x, -u.y);
        float m = mod(ang, setor) - 0.5 * setor;
        return length(u) * cos(m) / cos(PI / n) / tam;
    }
    float ang = mod(atan(u.x, -u.y), 2.0 * PI);
    return ang / (2.0 * PI) * divisions;
}

float degrau(float d, float largura, float aa) {
    // Largura zero: borda seca, só com o antialias de um pixel.
    float w = max(largura, aa);
    return clamp(d / w + 0.5, 0.0, 1.0);
}

void main() {
    vec4 fonte = texture(inputImg, acScreenNorm);
    vec2 res = acResolution;
    float esc = max(acEscalaDePixel, 1e-4);
    vec2 d = acScreenNorm * res - center * res;
    float tam = max(size, 1.0) * esc;

    float v = coordenada(d, tam);
    if (field == 1) v = -v;
    v -= offset + speed * acTime;

    // Antialias: quanto v anda num pixel (o AE suaviza a borda em ~1 px).
    float aa = fwidth(v);
    if (geometry == 4) {
        // O ângulo salta de 360° para 0° em cima: a derivada dali é falsa. Um
        // segundo ângulo, que salta EMBAIXO, dá a derivada certa no meridiano de cima.
        float th = radians(rotation);
        vec2 u = vec2(d.x * cos(th) + d.y * sin(th), -d.x * sin(th) + d.y * cos(th));
        float outro = atan(u.x, -u.y) / (2.0 * PI) * divisions;
        aa = min(aa, fwidth(outro));
    }
    aa = max(aa, 1e-5);

    float k = floor(v);
    float f = v - k;

    float s = startLine / 100.0;
    float p = progress / 100.0;
    float F = feather / 100.0;
    float pl = F > 0.0 ? p * (1.0 + F) - 0.5 * F : p;
    float e0 = s * (1.0 - pl);
    float e1 = e0 + pl;

    float m = 0.0;
    if (p > 0.0) {
        m = min(degrau(f - e0, s * F, aa), degrau(e1 - f, (1.0 - s) * F, aa));
        // A faixa vizinha: o antialias da borda f = 0/1 precisa ver o outro lado.
        if (e0 <= aa && e1 >= 1.0 - aa) m = 1.0;
        if (rangeMode == 1 && (k < rangeStart - 0.5 || k > rangeEnd + 0.5)) m = 0.0;
    }
    m *= opacity / 100.0;

    // Cor reta (não pré-multiplicada), como o compositor deste motor espera.
    if (blend == 0) {
        fragColor = vec4(fillColor.rgb, m * fonte.a);
    } else if (blend == 1) {
        fragColor = vec4(mix(fonte.rgb, fillColor.rgb, m), fonte.a);
    } else if (blend == 2) {
        fragColor = vec4(fonte.rgb, fonte.a * m);
    } else {
        fragColor = vec4(fonte.rgb, fonte.a * (1.0 - m));
    }
}
